'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex64Array = require( '@stdlib/array/complex64' );
var isSameComplex64 = require( '@stdlib/assert/is-same-complex64' );
var cdotu = require( './../lib/cdotu.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cdotu, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
	t.strictEqual( cdotu.length, 5, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the dot product of two single-precision complex floating-point vectors `zx` and `zy`', function test( t ) {
	var dot;
	var zx;
	var zy;

	zx = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 2.0, -5.0, 6.0 ] );
	zy = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 8.0, 2.0, -3.0 ] );

	dot = cdotu( 4, zx, 1, zy, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 3, 70 ) ), true, 'returns expected value' );

	zx = new Complex64Array( [ 3.0, -4.0, 1.0, 2.0 ] );
	zy = new Complex64Array( [ 1.0, -2.0, 3.0, 8.0 ] );

	dot = cdotu( 2, zx, 1, zy, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -18, 4 ) ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `0 + 0i`', function test( t ) {
	var dot;
	var zx;
	var zy;

	zx = new Complex64Array( [ 3.0, -4.0, 1.0, 7.0 ] );
	zy = new Complex64Array( [ 1.0, -2.0, 3.0, -3.0 ] );

	dot = cdotu( 0, zx, 1, zy, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 0, 0 ) ), true, 'returns expected value' );

	dot = cdotu( -4, zx, 1, zy, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 0, 0 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports an `zx` stride', function test( t ) {
	var dot;
	var zx;
	var zy;

	zx = new Complex64Array([
		2.0,  // 0
		-3.0, // 0
		-5.0,
		6.0,
		7.0,  // 1
		6.0   // 1
	]);
	zy = new Complex64Array([
		8.0,  // 0
		2.0,  // 0
		-3.0, // 1
		3.0,  // 1
		-4.0,
		1.0
	]);

	dot = cdotu( 2, zx, 2, zy, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -17, -17 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports a `zy` stride', function test( t ) {
	var dot;
	var zx;
	var zy;

	zx = new Complex64Array([
		2.0,  // 0
		-3.0, // 0
		-5.0, // 1
		7.0,  // 1
		6.0,
		-2.0
	]);
	zy = new Complex64Array([
		8.0,  // 0
		2.0,  // 0
		-3.0,
		3.0,
		-4.0, // 1
		1.0   // 1
	]);

	dot = cdotu( 2, zx, 1, zy, 2 );
	t.strictEqual( isSameComplex64( dot, new Complex64( 35, -53 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var dot;
	var zx;
	var zy;

	zx = new Complex64Array([
		1.0, // 1
		2.0, // 1
		3.0,
		4.0,
		5.0, // 0
		6.0  // 0
	]);
	zy = new Complex64Array([
		7.0,  // 1
		8.0,  // 1
		9.0,  // 0
		10.0, // 0
		11.0,
		12.0
	]);

	dot = cdotu( 2, zx, -2, zy, -1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -24, 126 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var dot;
	var zx;
	var zy;

	zx = new Complex64Array([
		1.0, // 0
		2.0, // 0
		3.0,
		4.0,
		5.0, // 1
		6.0  // 1
	]);
	zy = new Complex64Array([
		7.0,  // 0
		8.0,  // 0
		9.0,  // 1
		10.0, // 1
		11.0,
		12.0
	]);

	dot = cdotu( 2, zx, 2, zy, -1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -24, 110 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports view offsets', function test( t ) {
	var dot;
	var x0;
	var y0;
	var x1;
	var y1;

	x0 = new Complex64Array([
		1.0, // 0
		2.0, // 0
		3.0,
		4.0,
		5.0, // 1
		6.0  // 1
	]);
	y0 = new Complex64Array([
		7.0,
		8.0,
		9.0,  // 0
		10.0, // 0
		11.0, // 1
		12.0  // 1
	]);

	x1 = new Complex64Array( x0.buffer, x0.BYTES_PER_ELEMENT*0 );
	y1 = new Complex64Array( y0.buffer, y0.BYTES_PER_ELEMENT*1 );

	dot = cdotu( 2, x1, 2, y1, 1 );
	t.strictEqual( isSameComplex64( dot, new Complex64( -28, 154 ) ), true, 'returns expected value' );
	t.end();
});
